import { test, expect } from '@playwright/test';

test.describe('Search Suggestions Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display search suggestions for recently searched terms', async ({ page }) => {
    // Set up API interception for search API
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // Perform a search using getByRole
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('playwright');

    // Wait for suggestions to appear
    const suggestionsList = page.getByRole('listbox');
    await expect(suggestionsList).toBeVisible();

    // Verify suggestions are displayed
    const suggestionItems = page.locator('[data-testid="suggestion-item"]');
    await expect(suggestionItems).toHaveCount(3);

    // Verify each suggestion contains the correct text
    const suggestion1 = page.getByText('Playwright Test Library');
    await expect(suggestion1).toBeVisible();

    const suggestion2 = page.getByText('Playwright Playwright');
    await expect(suggestion2).toBeVisible();

    const suggestion3 = page.getByText('Playwright Playwright Playwright');
    await expect(suggestion3).toBeVisible();

    // Verify suggestion items have correct roles
    const suggestion1Role = page.getByRole('option');
    await expect(suggestion1Role).toBeVisible();

    const suggestion2Role = page.getByRole('option');
    await expect(suggestion2Role).toBeVisible();

    const suggestion3Role = page.getByRole('option');
    await expect(suggestion3Role).toBeVisible();

    // Verify suggestion items have correct data attributes
    const suggestion1Data = page.locator('[data-testid="suggestion-item"]').first();
    await expect(suggestion1Data).toHaveAttribute('data-testid', 'suggestion-item-1');

    const suggestion2Data = page.locator('[data-testid="suggestion-item"]').nth(1);
    await expect(suggestion2Data).toHaveAttribute('data-testid', 'suggestion-item-2');

    const suggestion3Data = page.locator('[data-testid="suggestion-item"]').nth(2);
    await expect(suggestion3Data).toHaveAttribute('data-testid', 'suggestion-item-3');

    // Verify suggestion list is visible and contains items
    await expect(suggestionsList).toBeVisible();
    await expect(suggestionItems).toHaveCount(3);

    // Verify search input is still visible
    await expect(searchInput).toBeVisible();
  });

  test('should clear search suggestions when user clears input', async ({ page }) => {
    // Set up API interception for search API
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // Perform a search using getByRole
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('playwright');

    // Wait for suggestions to appear
    const suggestionsList = page.getByRole('listbox');
    await expect(suggestionsList).toBeVisible();

    // Verify suggestions are displayed
    const suggestionItems = page.locator('[data-testid="suggestion-item"]');
    await expect(suggestionItems).toHaveCount(3);

    // Clear search input using getByRole
    const clearButton = page.getByRole('button', { name: /clear/i });
    await clearButton.click();

    // Verify suggestions are cleared
    await expect(suggestionsList).not.toBeVisible();

    // Verify search input is empty
    await expect(searchInput).toHaveValue('');

    // Verify no suggestions are displayed
    const suggestionItems = page.locator('[data-testid="suggestion-item"]');
    await expect(suggestionItems).toHaveCount(0);
  });
});
